package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){String reg=a.length>0?a[0]:"KL-071";try(Session s=HibernateUtil.getSessionFactory().openSession()){Long n=s.createQuery("select count(c) from CarDetail c where c.regNo=:reg",Long.class).setParameter("reg",reg).getSingleResult();System.out.println("Count for "+reg+": "+n);}HibernateUtil.getSessionFactory().close();}}